/**
 * Pricing rules for the storefront.
 *
 * Covers regional tax rates, category margins, volume discounts and the shipping thresholds used at
 * checkout, including the free-shipping threshold that applies to loyalty members.
 *
 * Values are in cents unless a name says otherwise. Add a rule next to the ones it resembles.
 */

export type Region = string;
export type Category = string;

export type TaxRule = { region: Region; category: Category; rateBasisPoints: number };
export type MarginRule = { category: Category; region: Region; minMarginBasisPoints: number };
export type VolumeDiscount = { category: Category; minQuantity: number; discountBasisPoints: number };

