export function taxRateFor(region: Region, category: Category): number {
  return TAX_RULES.find((rule) => rule.region === region && rule.category === category)?.rateBasisPoints ?? 2000;
}

export function volumeDiscountFor(category: Category, quantity: number): number {
  return VOLUME_DISCOUNTS.filter((rule) => rule.category === category && quantity >= rule.minQuantity).reduce(
    (best, rule) => Math.max(best, rule.discountBasisPoints),
    0,
  );
}
